'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var unaryReduceSubarrayBy = require( '@stdlib/ndarray/base/unary-reduce-subarray-by' );
var ndims = require( '@stdlib/ndarray/ndims' );
var base = require( '@stdlib/ndarray/base/find' );
var getDtype = require( '@stdlib/ndarray/dtype' );
var getShape = require( '@stdlib/ndarray/shape' );
var getOrder = require( '@stdlib/ndarray/base/order' );
var maybeBroadcastArray = require( '@stdlib/ndarray/base/maybe-broadcast-array' );
var broadcastScalar = require( '@stdlib/ndarray/base/broadcast-scalar' );
var zeroTo = require( '@stdlib/array/base/zero-to' );
var objectAssign = require( '@stdlib/object/assign' );
var format = require( '@stdlib/string/format' );
var DEFAULTS = require( './defaults.json' );
var validate = require( './validate.js' );
var getSentinelValue = require( './sentinel.js' );


// MAIN //

/**
* Finds the first elements which pass a test implemented by a predicate function along one or more ndarray dimensions and assigns results to a provided output ndarray.
*
* @param {ndarray} x - input ndarray
* @param {(*|ndarray)} [sentinelValue] - sentinel value
* @param {ndarray} out - output ndarray
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform a reduction
* @param {Function} predicate - predicate function
* @param {*} [thisArg] - predicate function execution context
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} third argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {TypeError} predicate argument must be a function
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* var isEven = require( '@stdlib/assert/is-even' ).isPrimitive;
* var array = require( '@stdlib/ndarray/array' );
* var empty = require( '@stdlib/ndarray/empty' );
*
* // Create an input ndarray:
* var x = array( [ [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ], [ [ 0.0, 6.0 ], [ 7.0, 8.0 ] ] ] );
* // returns <ndarray>
*
* // Create an output ndarray:
* var out = empty( [], {
*     'dtype': x.dtype
* });
*
* // Perform reduction:
* var result = assign( x, -1, out, isEven );
* // returns <ndarray>
*
* var v = out.get();
* // returns 2.0
*/
function assign( x ) {
	var sentinelValue;
	var predicate;
	var thisArg;
	var options;
	var nargs;
	var opts;
	var err;
	var out;
	var sv;
	var pi;
	var N;
	var i;

	nargs = arguments.length;
	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray-like object. Value: `%s`.', x ) );
	}
	pi = -1;
	for ( i = 1; i < nargs; i++ ) {
		if ( isFunction( arguments[ i ] ) ) {
			pi = i;
			break;
		}
	}
	if ( pi === -1 ) {
		throw new TypeError( 'invalid arguments. Must provide a predicate function. Value: `%s`.', arguments[ i ] );
	} else if ( pi === 2 ) { // assign( x, out, predicate [, thisArg] )
		out = arguments[ 1 ];
		predicate = arguments[ 2 ];
		if ( nargs === 4 ) {
			thisArg = arguments[ 3 ];
		}
	} else if ( pi === 3 ) {
		if ( isPlainObject( arguments[ 2 ] ) ) { // assign( x, out, options, predicate [, thisArg] )
			out = arguments[ 1 ];
			options = arguments[ 2 ];
			predicate = arguments[ 3 ];
			if ( nargs === 5 ) {
				thisArg = arguments[ 4 ];
			}
		} else { // assign( x, sentinel, out, predicate [, thisArg] )
			sentinelValue = arguments[ 1 ];
			out = arguments[ 2 ];
			predicate = arguments[ 3 ];
			if ( nargs === 5 ) {
				thisArg = arguments[ 4 ];
			}
		}
	} else { // assign( x, sentinel, out, options, predicate [, thisArg] )
		sentinelValue = arguments[ 1 ];
		out = arguments[ 2 ];
		options = arguments[ 3 ];
		predicate = arguments[ 4 ];
		if ( nargs === 6 ) {
			thisArg = arguments[ 5 ];
		}
	}
	if ( !isndarrayLike( out ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be an ndarray-like object. Value: `%s`.', out ) );
	}
	if ( options && !isPlainObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be a plain object. Value: `%s`.', options ) );
	}
	N = ndims( x );

	// Validate options
	opts = objectAssign( {}, DEFAULTS );
	if ( options ) {
		err = validate( opts, N, options );
		if ( err ) {
			throw err;
		}
	}

	// When a list of dimensions is not provided, reduce the entire input array across all dimensions...
	if ( opts.dims === null ) {
		opts.dims = zeroTo( N );
	}

	// Handle sentinel value:
	if ( sentinelValue === void 0 ) {
		sentinelValue = getSentinelValue( getDtype( x ) );
	}

	// Broadcast sentinel value to match the output array shape:
	if ( isndarrayLike( sentinelValue ) ) {
		sv = maybeBroadcastArray( sentinelValue, getShape( out ) );
	} else {
		sv = broadcastScalar( sentinelValue, getDtype( x ), getShape( out ), getOrder( out ) ); // eslint-disable-line max-len
	}

	// Perform the reduction:
	unaryReduceSubarrayBy( base, [ x, out, sv ], opts.dims, predicate, thisArg ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = assign;
